<?php
namespace App\Http\Controllers\Pelanggan;
use App\Http\Controllers\Controller;use App\Http\Requests\StoreBookingServisRequest;use App\Models\{BookingServis,JenisServis,Notifikasi,PromoMember,RiwayatPoin};use App\Services\{BookingServisService,ServicePersonnelAvailabilityService,ServiceSchedulingService,VehicleGalleryService,VerifiedCarOwnershipService};use Illuminate\Http\Request;use Throwable;
class BookingServisController extends Controller {
 private function customer(Request $r){$p=$r->user()->pelanggan;abort_unless($p,404);return $p;}
 public function index(Request $r){$cid=$this->customer($r)->id_pelanggan;$rows=BookingServis::with(['kendaraan','jenisServis','preferredPetugas','promo'])->where('id_pelanggan',$cid)->latest('tanggal')->latest('jam')->paginate(15);$activeBookingId=$r->integer('detail')?:null;$activeBooking=$activeBookingId?BookingServis::with(['kendaraan','jenisServis','preferredPetugas','promo'])->where('id_pelanggan',$cid)->find($activeBookingId):null;return view('pelanggan.booking-servis.index',compact('rows','activeBooking','activeBookingId'));}
 public function create(Request $r,VehicleGalleryService $gallery,VerifiedCarOwnershipService $ownership){$p=$this->customer($r);$vehicles=$p->kendaraan()->where('status','aktif')->with(['penjualan.mobil','pesanan'])->orderBy('merk')->orderBy('model')->get();$selectedVehicleId=(int)$r->integer('kendaraan');abort_if($selectedVehicleId && !$vehicles->contains('id_kendaraan_pelanggan',$selectedVehicleId),404);$vehicles->each(function($vehicle)use($gallery,$ownership,$p):void{$mobil=$vehicle->penjualan?->mobil;$purchasedColor=$vehicle->pesanan?->snapshot_warna ?: $vehicle->warna;$selected=$mobil?$gallery->forColor($mobil,$purchasedColor):[];if(!$selected&&!$purchasedColor&&$mobil)$selected=$gallery->for($mobil)[$gallery->defaultColor($mobil)]??[];$vehicle->setAttribute('booking_image',$selected['images'][0]['src']??asset('assets/images/hero/yza-hero-reference-v3.png'));$vehicle->setAttribute('is_verified_ownership',$ownership->vehicleBelongsToVerifiedPurchase((int)$p->id_pelanggan,(int)$vehicle->id_kendaraan_pelanggan));});$types=JenisServis::where('status','aktif')->orderBy('nama_servis')->get();$allVisiblePromos=PromoMember::visible()->orderBy('selesai_at')->get();$claimedPromoCodes=RiwayatPoin::where('id_pelanggan',$p->id_pelanggan)->where('jenis','penukaran')->pluck('keterangan')->map(fn($ket)=>preg_match('/\((YZA-[A-Z0-9]+)\)/i',(string)$ket,$m)?strtoupper($m[1]):null)->filter()->unique()->values()->all();$claimedPromoIds=Notifikasi::where('id_user',$p->id_user)->where('referensi_tipe','promo')->pluck('referensi_id')->map(fn($id)=>(int)$id)->all();$isClaimed=fn(PromoMember $promo)=>(int)($promo->points_cost??0)===0||in_array(strtoupper((string)$promo->kode_promo),$claimedPromoCodes,true)||in_array((int)$promo->id_promo,$claimedPromoIds,true);$claimedPromos=$allVisiblePromos->filter($isClaimed)->values();$unclaimedAll=$allVisiblePromos->reject($isClaimed)->sortByDesc(fn(PromoMember $promo)=>in_array($promo->berlaku_untuk,['servis','semua'],true)?1:0)->values();$unclaimedPromos=$unclaimedAll;$totalUnclaimedCount=$unclaimedAll->count();return view('pelanggan.booking-servis.create',compact('vehicles','types','selectedVehicleId','claimedPromos','unclaimedPromos','totalUnclaimedCount'));}
 public function store(StoreBookingServisRequest $req,BookingServisService $svc){try{$d=$req->validated();$b=$svc->create($this->customer($req)->id_pelanggan,(int)$d['id_kendaraan_pelanggan'],(int)$d['id_jenis_servis'],$d['tanggal'],$d['jam'],$d['keluhan']??null,$d['catatan']??null,isset($d['id_preferred_petugas'])?(int)$d['id_preferred_petugas']:null,isset($d['id_promo'])?(int)$d['id_promo']:null);return redirect()->route('pelanggan.booking-servis.index')->with('success','Booking servis berhasil diajukan.');}catch(Throwable $e){$message=str_contains($e->getMessage(),'Teknisi tidak aktif')?'Teknisi pilihan Anda sudah tidak tersedia pada jadwal tersebut. Silakan pilih teknisi lain atau lanjutkan tanpa preferensi.':$e->getMessage();return back()->withInput()->withErrors($message);}}
 public function availability(Request $r,ServiceSchedulingService $s){$d=$r->validate(['date'=>'nullable|required_without:month|date_format:Y-m-d','month'=>'nullable|required_without:date|date_format:Y-m','jenis_servis_id'=>'required|integer|exists:jenis_servis,id_jenis_servis']);return response()->json(isset($d['month'])?$s->monthAvailability($d['month'],(int)$d['jenis_servis_id']):$s->availability($d['date'],(int)$d['jenis_servis_id']));}
 public function technicians(Request $r,ServicePersonnelAvailabilityService $s){$d=$r->validate(['date'=>'required|date_format:Y-m-d','time'=>'required|date_format:H:i','jenis_servis_id'=>'required|integer|exists:jenis_servis,id_jenis_servis']);return response()->json(['date'=>$d['date'],'time'=>$d['time'],'jenis_servis_id'=>(int)$d['jenis_servis_id'],'technicians'=>$s->technicians($d['date'],$d['time'],(int)$d['jenis_servis_id'])]);}
 public function show(Request $r,BookingServis $booking_servis){$cid=$this->customer($r)->id_pelanggan;abort_unless((int)$booking_servis->id_pelanggan===(int)$cid,403);$booking_servis->load(['kendaraan','jenisServis','preferredPetugas','promo']);$rows=BookingServis::with(['kendaraan','jenisServis','preferredPetugas','promo'])->where('id_pelanggan',$cid)->latest('tanggal')->latest('jam')->paginate(15);$activeBooking=$booking_servis;$activeBookingId=$booking_servis->getKey();return view('pelanggan.booking-servis.index',compact('rows','activeBooking','activeBookingId'));}
 public function cancel(Request $r,BookingServis $booking_servis,BookingServisService $svc){abort_unless((int)$booking_servis->id_pelanggan===(int)$this->customer($r)->id_pelanggan,403);try{$svc->cancel($booking_servis->id_booking_servis,$this->customer($r)->id_pelanggan);return back()->with('success','Booking servis dibatalkan.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}
}
